create or replace function app.assert_profit_distribution_snapshot(p_distribution_id uuid) returns void language plpgsql security definer set search_path='' as $$declare v_distribution public.profit_distributions%rowtype;v_revenue numeric(20,2);v_expenses numeric(20,2);v_operating_profit numeric(20,2);v_opex numeric(20,2);v_profit numeric(20,2);begin select * into v_distribution from public.profit_distributions where id=p_distribution_id;if v_distribution.financial_report_version_id is null then raise exception 'Profit distribution requires a financial report snapshot.' using errcode='23514';end if;select max(amount) filter(where line_key='revenue_total'),max(amount) filter(where line_key='expense_total') into v_revenue,v_expenses from public.financial_line_items where financial_report_version_id=v_distribution.financial_report_version_id;if v_revenue is null or v_expenses is null then raise exception 'Published financial report must contain canonical revenue_total and expense_total line items.' using errcode='23514';end if;v_operating_profit:=greatest(v_revenue-v_expenses,0);v_opex:=round(v_operating_profit*v_distribution.opex_rate_bps/10000.0,2);v_profit:=greatest(v_operating_profit-v_opex,0);if v_distribution.revenue_amount<>v_revenue or v_distribution.operating_expense_amount<>v_expenses or v_distribution.opex_amount<>v_opex or v_distribution.profit_amount<>v_profit or v_distribution.investor_pool_amount<>round(v_profit*app.eligible_ownership_bps_at_cutoff(v_distribution.offering_id,app.accounting_period_cutoff(v_distribution.period_end))/10000.0,2) then raise exception 'Profit distribution no longer reconciles with its financial report snapshot.' using errcode='23514';end if;end$$;